// Constructor Injection (recommended for required dependencies)
@Service
public class OrderService {
    private final OrderRepository orderRepo;  // final = immutable

    public OrderService(OrderRepository orderRepo) {  // no @Autowired needed
        this.orderRepo = orderRepo;
    }
}

// Setter Injection (for optional dependencies)
@Service
public class NotificationService {
    private EmailClient emailClient;

    @Autowired(required = false)  // Spring injects if bean exists
    public void setEmailClient(EmailClient emailClient) {
        this.emailClient = emailClient;
    }
}

// Field Injection (discouraged in production)
@Service
public class UserService {
    @Autowired  // Spring sets this via reflection
    private UserRepository userRepo;  // cannot be final, hard to test
}

@Service
public class OrderService {
    // Required dependency: constructor injection with final
    private final OrderRepository orderRepo;
    private final PaymentGateway paymentGateway;

    // Optional dependency: setter injection
    private CacheService cacheService;

    // Constructor for required dependencies (no @Autowired needed)
    public OrderService(OrderRepository orderRepo, PaymentGateway paymentGateway) {
        this.orderRepo = orderRepo;
        this.paymentGateway = paymentGateway;
    }

    // Setter for optional dependency
    @Autowired(required = false)
    public void setCacheService(CacheService cacheService) {
        this.cacheService = cacheService;
    }

    public Order findOrder(Long id) {
        if (cacheService != null) {  // Use cache if available
            return cacheService.get(id, () -> orderRepo.findById(id));
        }
        return orderRepo.findById(id);  // Fallback to direct DB query
    }
}

// Constructor injection: clean unit test in 3 lines
@Test
void testOrderCreation_ConstructorInjection() {
    var mockRepo = Mockito.mock(OrderRepository.class);
    var service = new OrderService(mockRepo);  // Just works
    // test service methods...
}

// Field injection: requires Spring context or reflection
@SpringBootTest  // Starts entire Spring app, slow
class OrderServiceTest {
    @Autowired
    private OrderService service;  // Can't new it up

    @MockBean  // Special Spring test annotation
    private OrderRepository orderRepo;
}

// OR: Field injection with reflection hack
@Test
void testOrderCreation_FieldInjection() {
    var mockRepo = Mockito.mock(OrderRepository.class);
    var service = new OrderService();  // Deps are null
    ReflectionTestUtils.setField(service, "orderRepo", mockRepo);  // Brittle
    // test service methods...
}

// Modern Spring Boot: no @Autowired needed
@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final PaymentGateway paymentGateway;

    // Single constructor: Spring uses it automatically
    public OrderService(OrderRepository orderRepo, PaymentGateway paymentGateway) {
        this.orderRepo = orderRepo;
        this.paymentGateway = paymentGateway;
    }
}

// Even cleaner with Lombok: generates constructor for final fields
@Service
@RequiredArgsConstructor  // Lombok creates constructor for all final fields
public class CustomerService {
    private final CustomerRepository customerRepo;
    private final EmailService emailService;
    // No constructor code needed, Lombok generates it at compile time
}

// Multiple constructors: need @Autowired to disambiguate
@Service
public class ReportService {
    private final ReportRepository reportRepo;

    @Autowired  // Required: tells Spring which constructor to use
    public ReportService(ReportRepository reportRepo) {
        this.reportRepo = reportRepo;
    }

    public ReportService() {  // No-arg constructor for testing
        this.reportRepo = null;
    }
}
